// Validate input
const body = $input.first().json.body || $input.first().json;
const text = body.text || '';
const voice = body.voice || 'nova';
const speed = body.speed || 1.0;
const model = body.model || 'tts-1';

if (!text) {
  throw new Error('Parameter "text" is required');
}

if (text.length > 4096) {
  throw new Error('Text too long (max 4096 chars)');
}

// Valid OpenAI voices: alloy, echo, fable, onyx, nova, shimmer
const validVoices = ['alloy', 'echo', 'fable', 'onyx', 'nova', 'shimmer'];
if (!validVoices.includes(voice)) {
  throw new Error(`Invalid voice. Must be one of: ${validVoices.join(', ')}`);
}

// Generate filename
const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
const filename = `jarvis-tts-${timestamp}.mp3`;

return [{
  json: {
    text: text,
    voice: voice,
    speed: speed,
    model: model,
    filename: filename
  }
}];

// Build response with Supabase public URL
const filename = $('Validate Input').first().json.filename;
const publicUrl = `https://omykcphkzmmqpwswwfsw.supabase.co/storage/v1/object/public/jarvis-audio/${filename}`;

return [{
  json: {
    success: true,
    filename: filename,
    public_url: publicUrl,
    bucket: 'jarvis-audio',
    created_at: new Date().toISOString()
  }
}];
